from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=1)
def compute_jacobi1D(input, i):
    if i == 0:
        return (input[i] + input[i + 1])/3
    elif i == len(input) - 1:
        return (input[i - 1] + input[i])/3
    else:
        return (input[i - 1] + input[i] + input[i + 1])/3

def main(input):
    output = [compute_jacobi1D(input, i) for i in range(len(input))]
    output = compss_wait_on(output)
    return output
